1	//! SPSC ring v0: the load/store-only single-producer
2	//! single-consumer protocol, per
3	//! [notes/ring-buffer-design.md]:
4	//!
5	//! - One `#[repr(C)]` [`Header`] spanning four cache lines
6	//!   (immutable geometry, producer index, consumer index, app
7	//!   user words), followed by M slots of N bytes.
8	//! - Indices are free-running `AtomicU32`s, masked only at slot
9	//!   access; full is `p - c == M`, no sacrificial slot.
10	//! - Messages move in place: the producer writes through a
11	//!   [`WriteSlot`] `&mut T`, the consumer reads through a
12	//!   [`ReadSlot`] `&T` — zerocopy traits bound `T`, no
13	//!   serialization step. Each side reserves at most one slot at
14	//!   a time; the guard holds the endpoint borrow until commit /
15	//!   release (or drop).
16	//!
17	//! [notes/ring-buffer-design.md]: https://github.com/winksaville/zc-ring-x1/blob/main/notes/ring-buffer-design.md
18	
19	use core::marker::PhantomData;
20	use core::mem::size_of;
21	use core::sync::atomic::{AtomicU32, Ordering};
22	
23	use crate::{CACHE_LINE_SIZE, CacheAligned, Error, USER_WORDS};
24	
25	mod consumer;
26	mod producer;
27	
28	pub use consumer::{Consumer, ReadSlot};
29	pub use producer::{Producer, WriteSlot};
30	
31	/// Layout marker written by [`Ring::init`]; rejects foreign
32	/// regions on attach.
33	const MAGIC: u32 = 0x5A43_5231; // "ZCR1"
34	
35	/// Bumped on any change to the region layout.
36	const LAYOUT_VERSION: u32 = 2;
37	
38	/// Control block at offset 0 of the region — one struct spanning
39	/// four cache lines so each concurrently-written index owns its
40	/// own line.
41	///
42	/// - line 0: geometry, written by [`Ring::init`] with `magic`
43	///   last (`Release`), read-only thereafter. Cold: per-op
44	///   paths use the handles' snapshots.
45	/// - line 1: `producer_idx`, written only by the producer.
46	/// - line 2: `consumer_idx`, written only by the consumer.
47	/// - line 3: `user`, app-owned scratch — last, so an app
48	///   overrun walks into its own slot data, not an index line.
49	/// - Every field is atomic: the region may be mapped by a peer
50	///   at any time, so even "immutable" fields must be free of
51	///   data races. `AtomicU32` has the same layout as `u32`, so
52	///   this does not affect `layout_version`.
53	#[repr(C)]
54	pub struct Header {
55	    /// Layout marker ([`MAGIC`]); stored last by init
56	    /// (`Release`), loaded first by attach (`Acquire`), so a
57	    /// peer that observes it also observes the geometry.
58	    magic: AtomicU32,
59	    /// Layout version ([`LAYOUT_VERSION`]).
60	    layout_version: AtomicU32,
61	    /// Slot size N in bytes — a [`CACHE_LINE_SIZE`] multiple.
62	    slot_size: AtomicU32,
63	    /// Slot count M — a power of two `<= 2^31`.
64	    capacity: AtomicU32,
65	    /// [`CACHE_LINE_SIZE`] this region was built with. The line size
66	    /// is a layout parameter (padding, offsets, slot granule),
67	    /// so builds must agree; attach validates it like the rest
68	    /// of the geometry.
69	    cache_line_size: AtomicU32,
70	    /// Free-running count of messages committed.
71	    producer_idx: CacheAligned<AtomicU32>,
72	    /// Free-running count of messages released.
73	    consumer_idx: CacheAligned<AtomicU32>,
74	    /// App-owned scratch line ([`USER_WORDS`] words): zeroed by
75	    /// init, then never read, written, or interpreted by the
76	    /// crate. See the design doc's "Blocking and user words".
77	    user: CacheAligned<[AtomicU32; USER_WORDS]>,
78	}
79	
80	const _: () = assert!(size_of::<Header>() == 4 * CACHE_LINE_SIZE);
81	
82	/// A validated view over a ring region; split into the two
83	/// endpoint handles with [`Ring::split`].
84	///
85	/// - Geometry is snapshotted out of the header at
86	///   init/attach: per-op paths never re-read fields a peer
87	///   could scribble on, so a hostile peer can degrade the ring
88	///   to garbage messages or spurious Full/Empty, never to UB.
89	pub struct Ring<'a> {
90	    /// The region's control block.
91	    header: &'a Header,
92	    /// Base of the slot array (offset `size_of::<Header>()`).
93	    slots: *mut u8,
94	    /// Snapshot of `header.slot_size`.
95	    slot_size: u32,
96	    /// Snapshot of `header.capacity`.
97	    capacity: u32,
98	    /// Slot-position mask (`capacity - 1`).
99	    mask: u32,
100	    _region: PhantomData<&'a [u8]>,
101	}
102	
103	impl<'a> Ring<'a> {
104	    /// Initialize a fresh region and return the ring over it.
105	    ///
106	    /// - `slot_size` — N bytes per slot, a [`CACHE_LINE_SIZE`]
107	    ///   multiple.
108	    /// - `capacity` — M slots, a power of two `<= 2^31`.
109	    /// - The region must be [`CACHE_LINE_SIZE`]-aligned and at least
110	    ///   `size_of::<Header>() + M * N` bytes.
111	    pub fn init(region: &'a mut [u8], slot_size: u32, capacity: u32) -> Result<Self, Error> {
112	        validate_geometry(slot_size, capacity)?;
113	        let len = region.len();
114	        // Taken exactly once: a second `as_mut_ptr()` would
115	        // retag the slice and invalidate `header` under Stacked
116	        // Borrows (Miri-verified).
117	        let base = region.as_mut_ptr();
118	        let header = header_ptr(base, len)?;
119	        if (len as u64) < region_size(slot_size, capacity) {
120	            return Err(Error::TooSmall);
121	        }
122	        // SAFETY: alignment + room for the Header checked by
123	        // header_ptr; region is exclusively borrowed for 'a;
124	        // any byte pattern is a valid Header (all-atomic
125	        // fields, plain-byte padding).
126	        let header = unsafe { &*header };
127	        header
128	            .layout_version
129	            .store(LAYOUT_VERSION, Ordering::Relaxed);
130	        header.slot_size.store(slot_size, Ordering::Relaxed);
131	        header.capacity.store(capacity, Ordering::Relaxed);
132	        header
133	            .cache_line_size
134	            .store(CACHE_LINE_SIZE as u32, Ordering::Relaxed);
135	        header.producer_idx.store(0, Ordering::Relaxed);
136	        header.consumer_idx.store(0, Ordering::Relaxed);
137	        for word in header.user.iter() {
138	            word.store(0, Ordering::Relaxed);
139	        }
140	        // Published last: a peer that pre-mapped the region must
141	        // never observe MAGIC before the geometry it validates.
142	        // (Re-initializing a region a peer is already attached
143	        // to is outside the contract.)
144	        header.magic.store(MAGIC, Ordering::Release);
145	        // SAFETY: in bounds — region.len() >= header + slots.
146	        let slots = unsafe { base.add(size_of::<Header>()) };
147	        Ok(Ring {
148	            header,
149	            slots,
150	            slot_size,
151	            capacity,
152	            mask: capacity - 1,
153	            _region: PhantomData,
154	        })
155	    }
156	
157	    /// Attach to a region another process (or an earlier call)
158	    /// already initialized, validating its header.
159	    ///
160	    /// # Safety
161	    ///
162	    /// - `region` points to `len` bytes of memory that outlive
163	    ///   `'a`, genuinely shared and writable (e.g. a
164	    ///   `MAP_SHARED` mapping).
165	    /// - No other producer attaches if this side will produce;
166	    ///   likewise for the consumer side (SPSC contract).
167	    pub unsafe fn attach(region: *mut u8, len: usize) -> Result<Self, Error> {
168	        let header = header_ptr(region, len)?;
169	        // SAFETY: alignment + room for the Header checked by
170	        // header_ptr; caller guarantees the memory is live and
171	        // shared.
172	        let header = unsafe { &*header };
173	        // Acquire pairs with init's Release store of magic: a
174	        // valid magic means the geometry stores are visible.
175	        if header.magic.load(Ordering::Acquire) != MAGIC {
176	            return Err(Error::BadMagic);
177	        }
178	        if header.layout_version.load(Ordering::Relaxed) != LAYOUT_VERSION {
179	            return Err(Error::BadLayoutVersion);
180	        }
181	        if header.cache_line_size.load(Ordering::Relaxed) != CACHE_LINE_SIZE as u32 {
182	            return Err(Error::BadCacheLine);
183	        }
184	        // Snapshot geometry once; per-op paths never re-read it.
185	        let slot_size = header.slot_size.load(Ordering::Relaxed);
186	        let capacity = header.capacity.load(Ordering::Relaxed);
187	        validate_geometry(slot_size, capacity)?;
188	        if (len as u64) < region_size(slot_size, capacity) {
189	            return Err(Error::TooSmall);
190	        }
191	        // SAFETY: in bounds — len >= header + slots.
192	        let slots = unsafe { region.add(size_of::<Header>()) };
193	        Ok(Ring {
194	            header,
195	            slots,
196	            slot_size,
197	            capacity,
198	            mask: capacity - 1,
199	            _region: PhantomData,
200	        })
201	    }
202	
203	    /// Split into the producer and consumer endpoint handles.
204	    ///
205	    /// - Consuming `self` makes each handle exist at most once
206	    ///   per ring per process; cross-process, one producing and
207	    ///   one consuming process is the SPSC contract.
208	    pub fn split(self) -> (Producer<'a>, Consumer<'a>) {
209	        (
210	            Producer::new(
211	                self.header,
212	                self.slots,
213	                self.slot_size,
214	                self.capacity,
215	                self.mask,
216	            ),
217	            Consumer::new(self.header, self.slots, self.slot_size, self.mask),
218	        )
219	    }
220	}
221	
222	/// Validate a region base pointer and cast it to the `Header`
223	/// it must start with; shared by [`Ring::init`] / [`Ring::attach`].
224	///
225	/// - Checks alignment and room for the `Header` itself. The
226	///   full-geometry length check stays with the caller: init
227	///   knows the geometry from its parameters, attach only after
228	///   reading it from the returned header.
229	/// - Returns a raw pointer — no deref here. Each caller
230	///   discharges its own safety obligation (init: exclusive
231	///   borrow; attach: the caller's shared-mapping contract).
232	fn header_ptr(base: *mut u8, len: usize) -> Result<*const Header, Error> {
233	    if !(base as usize).is_multiple_of(CACHE_LINE_SIZE) {
234	        return Err(Error::Misaligned);
235	    }
236	    if len < size_of::<Header>() {
237	        return Err(Error::TooSmall);
238	    }
239	    Ok(base as *const Header)
240	}
241	
242	/// Bytes needed for a region with the given geometry.
243	///
244	/// - Computed in u64: the usize product can wrap on 32-bit
245	///   targets (e.g. N = 2^26, M = 2^6), which would validate a
246	///   tiny region and let safe code write out of bounds.
247	fn region_size(slot_size: u32, capacity: u32) -> u64 {
248	    size_of::<Header>() as u64 + slot_size as u64 * capacity as u64
249	}
250	
251	/// Shared geometry checks for [`Ring::init`] / [`Ring::attach`].
252	fn validate_geometry(slot_size: u32, capacity: u32) -> Result<(), Error> {
253	    if slot_size == 0 || !(slot_size as usize).is_multiple_of(CACHE_LINE_SIZE) {
254	        return Err(Error::BadSlotSize);
255	    }
256	    // The `> 1 << 31` arm is unreachable (u32 powers of two are
257	    // <= 2^31); it stays to document the M bound the occupancy
258	    // math relies on.
259	    if capacity == 0 || !capacity.is_power_of_two() || capacity > 1 << 31 {
260	        return Err(Error::BadCapacity);
261	    }
262	    Ok(())
263	}
