271	    /// Test message; two words so a torn write would be visible.
272	    #[derive(FromBytes, IntoBytes, KnownLayout, Immutable, Debug, PartialEq)]
273	    #[repr(C)]
274	    struct Msg {
275	        seq: u64,
276	        val: u64,
277	    }
278	
279	    /// Test region size: header + (4 slots × 1 line each).
280	    const REGION_BYTES: usize = size_of::<Header>() + (4 * CACHE_LINE_SIZE);
281	
282	    /// Cache-line-aligned backing store for the tests' rings.
283	    #[repr(C, align(64))]
284	    struct Region([u8; REGION_BYTES]);
285	
286	    impl Region {
287	        fn new() -> Self {
288	            Region([0; REGION_BYTES])
289	        }
290	    }
