292	    #[test]
293	    fn init_rejects_bad_geometry() {
294	        let mut r = Region::new();
295	        assert_eq!(
296	            Ring::init(&mut r.0, 63, 4).err().unwrap(),
297	            Error::BadSlotSize
298	        );
299	        assert_eq!(
300	            Ring::init(&mut r.0, 0, 4).err().unwrap(),
301	            Error::BadSlotSize
302	        );
303	        assert_eq!(
304	            Ring::init(&mut r.0, 64, 3).err().unwrap(),
305	            Error::BadCapacity
306	        );
307	        assert_eq!(
308	            Ring::init(&mut r.0, 64, 0).err().unwrap(),
309	            Error::BadCapacity
310	        );
311	        assert_eq!(Ring::init(&mut r.0, 64, 8).err().unwrap(), Error::TooSmall);
312	        assert_eq!(
313	            Ring::init(&mut r.0[1..], 64, 4).err().unwrap(),
314	            Error::Misaligned
315	        );
316	        // 32-bit tripwire: N * M wraps a 32-bit usize (2^26 *
317	        // 2^6 = 2^32); the u64 region_size must still reject it.
318	        assert_eq!(
319	            Ring::init(&mut r.0, 1 << 26, 1 << 6).err().unwrap(),
320	            Error::TooSmall
321	        );
322	    }
