324	    #[test]
325	    fn attach_validates_header() {
326	        let mut r = Region::new();
327	        // Not initialized yet: magic is zero.
328	        let err = unsafe { Ring::attach(r.0.as_mut_ptr(), r.0.len()) }
329	            .err()
330	            .unwrap();
331	        assert_eq!(err, Error::BadMagic);
332	        Ring::init(&mut r.0, 64, 4).unwrap();
333	        let ring = unsafe { Ring::attach(r.0.as_mut_ptr(), r.0.len()) }.unwrap();
334	        assert_eq!(ring.slot_size, 64);
335	        assert_eq!(ring.capacity, 4);
336	        assert_eq!(ring.mask, 3);
337	        // A region built with a different CACHE_LINE_SIZE (simulated
338	        // by editing the recorded value) is rejected.
339	        ring.header.cache_line_size.store(128, Ordering::Relaxed);
340	        let err = unsafe { Ring::attach(r.0.as_mut_ptr(), r.0.len()) }
341	            .err()
342	            .unwrap();
343	        assert_eq!(err, Error::BadCacheLine);
344	    }
