346	    #[test]
347	    fn user_words_zeroed_and_shared() {
348	        let mut r = Region::new();
349	        // Dirty the region so init's zeroing is observable.
350	        r.0.fill(0xAA);
351	        let ring = Ring::init(&mut r.0, 64, 4).unwrap();
352	        let (prod, mut cons) = ring.split();
353	        assert!(prod.user().iter().all(|w| w.load(Ordering::Relaxed) == 0));
354	        // Both endpoints see the same line; a producer-side
355	        // store is visible through the consumer's accessor.
356	        prod.user()[0].store(7, Ordering::Release);
357	        assert_eq!(cons.user()[0].load(Ordering::Acquire), 7);
358	        // The user line must not alias ring state: scribbling
359	        // all of it leaves the ring empty and functional.
360	        for w in cons.user().iter() {
361	            w.store(u32::MAX, Ordering::Relaxed);
362	        }
363	        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
364	    }
