366	    #[test]
367	    fn indices_survive_u32_wrap() {
368	        let mut r = Region::new();
369	        let ring = Ring::init(&mut r.0, 64, 4).unwrap();
370	        // Simulate a long-running ring two commits shy of the
371	        // u32 wrap (empty state: p == c).
372	        let start = u32::MAX - 1;
373	        ring.header.producer_idx.store(start, Ordering::Relaxed);
374	        ring.header.consumer_idx.store(start, Ordering::Relaxed);
375	        let (mut prod, mut cons) = ring.split();
376	
377	        // Fill: producer_idx runs MAX-1, MAX, 0, 1 — masked
378	        // slot positions 2, 3, 0, 1.
379	        for i in 0..4u64 {
380	            let mut slot = prod.reserve_slot_with::<Msg>(|_| false).unwrap();
381	            slot.seq = i;
382	            slot.val = i;
383	            slot.commit();
384	        }
385	        assert!(prod.reserve_slot_with::<Msg>(|_| false).is_err());
386	
387	        // Drain in order across the wrap.
388	        for i in 0..4u64 {
389	            let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
390	            assert_eq!(msg.seq, i);
391	            msg.release();
392	        }
393	        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
394	    }
