396	    #[test]
397	    fn roundtrip_full_empty() {
398	        let mut r = Region::new();
399	        let (mut prod, mut cons) = Ring::init(&mut r.0, 64, 4).unwrap().split();
400	
401	        // Empty at start.
402	        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
403	
404	        // Fill all 4 slots, then Full.
405	        for i in 0..4u64 {
406	            let mut slot = prod.reserve_slot_with::<Msg>(|_| false).unwrap();
407	            slot.seq = i;
408	            slot.val = i * 10;
409	            slot.commit();
410	        }
411	        assert!(prod.reserve_slot_with::<Msg>(|_| false).is_err());
412	
413	        // Drain in order; wrap: slot 0 is reused by seq 4.
414	        for i in 0..4u64 {
415	            let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
416	            assert_eq!(
417	                *msg,
418	                Msg {
419	                    seq: i,
420	                    val: i * 10
421	                }
422	            );
423	            msg.release();
424	        }
425	        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
426	
427	        // One more write lands in the masked-around slot 0.
428	        let mut slot = prod.reserve_slot_with::<Msg>(|_| false).unwrap();
429	        slot.seq = 4;
430	        slot.commit();
431	        let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
432	        assert_eq!(msg.seq, 4);
433	        msg.release();
434	    }
