436	    #[test]
437	    // Dropping the guards is the behavior under test; they have
438	    // no Drop impl by design (abandon = do nothing).
439	    #[allow(clippy::drop_non_drop)]
440	    fn abandoned_guards_publish_nothing() {
441	        let mut r = Region::new();
442	        let (mut prod, mut cons) = Ring::init(&mut r.0, 64, 4).unwrap().split();
443	
444	        // Reserve then drop: nothing published.
445	        let mut slot = prod.reserve_slot_with::<Msg>(|_| false).unwrap();
446	        slot.seq = 99;
447	        drop(slot);
448	        assert!(cons.reserve_slot_with::<Msg>(|_| false).is_err());
449	
450	        // Commit one, reserve then drop: still unread, the
451	        // next reservation returns it again.
452	        let mut slot = prod.reserve_slot_with::<Msg>(|_| false).unwrap();
453	        slot.seq = 1;
454	        slot.commit();
455	        let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
456	        assert_eq!(msg.seq, 1);
457	        drop(msg);
458	        let msg = cons.reserve_slot_with::<Msg>(|_| false).unwrap();
459	        assert_eq!(msg.seq, 1);
460	        msg.release();
461	    }
