463	    #[test]
464	    fn threaded_spsc() {
465	        // Reduced under Miri: interpreted spin loops are slow,
466	        // and its scheduler explores interleavings at any count.
467	        const COUNT: u64 = if cfg!(miri) { 200 } else { 100_000 };
468	        let mut r = Region::new();
469	        let (mut prod, mut cons) = Ring::init(&mut r.0, 64, 4).unwrap().split();
470	
471	        std::thread::scope(|s| {
472	            s.spawn(move || {
473	                for i in 0..COUNT {
474	                    loop {
475	                        match prod.reserve_slot_with::<Msg>(|_| false) {
476	                            Ok(mut slot) => {
477	                                slot.seq = i;
478	                                slot.val = i * 3;
479	                                slot.commit();
480	                                break;
481	                            }
482	                            Err(Full) => std::hint::spin_loop(),
483	                        }
484	                    }
485	                }
486	            });
487	            s.spawn(move || {
488	                for i in 0..COUNT {
489	                    loop {
490	                        match cons.reserve_slot_with::<Msg>(|_| false) {
491	                            Ok(msg) => {
492	                                assert_eq!(msg.seq, i);
493	                                assert_eq!(msg.val, i * 3);
494	                                msg.release();
495	                                break;
496	                            }
497	                            Err(Empty) => std::hint::spin_loop(),
498	                        }
499	                    }
500	                }
501	            });
502	        });
503	    }
