505	    #[test]
506	    fn reserve_slot_with_policy_counts_and_gives_up() {
507	        let mut r = Region::new();
508	        let (mut prod, mut cons) = Ring::init(&mut r.0, 64, 4).unwrap().split();
509	
510	        // Empty ring: the consumer's policy sees 0-based
511	        // attempts and its `false` becomes Err(Empty).
512	        let mut seen = Vec::new();
513	        let err = cons
514	            .reserve_slot_with::<Msg>(|attempt| {
515	                seen.push(attempt);
516	                attempt < 2
517	            })
518	            .err()
519	            .unwrap();
520	        assert_eq!(err, Empty);
521	        assert_eq!(seen, [0, 1, 2]);
522	
523	        // Fill the ring: the producer's policy gives up with
524	        // Err(Full).
525	        for i in 0..4 {
526	            let mut slot = prod.reserve_slot_with::<Msg>(|_| false).unwrap();
527	            slot.seq = i;
528	            slot.commit();
529	        }
530	        let err = prod
531	            .reserve_slot_with::<Msg>(|attempt| attempt < 2)
532	            .err()
533	            .unwrap();
534	        assert_eq!(err, Full);
535	
536	        // With room / messages available the policy is never
537	        // consulted.
538	        let msg = cons
539	            .reserve_slot_with::<Msg>(|_| panic!("policy consulted with a message available"))
540	            .unwrap();
541	        assert_eq!(msg.seq, 0);
542	        msg.release();
543	        let mut slot = prod
544	            .reserve_slot_with::<Msg>(|_| panic!("policy consulted with room available"))
545	            .unwrap();
546	        slot.seq = 4;
547	        slot.commit();
548	    }
