550	    #[test]
551	    fn threaded_spsc_spin_variants() {
552	        // The threaded_spsc flow through the shipped
553	        // policy::spin on both ends — the shipped-policy model
554	        // in use.
555	        const COUNT: u64 = if cfg!(miri) { 200 } else { 100_000 };
556	        let mut r = Region::new();
557	        let (mut prod, mut cons) = Ring::init(&mut r.0, 64, 4).unwrap().split();
558	
559	        std::thread::scope(|s| {
560	            s.spawn(move || {
561	                for i in 0..COUNT {
562	                    let mut slot = prod.reserve_slot_with::<Msg>(crate::policy::spin).unwrap();
563	                    slot.seq = i;
564	                    slot.val = i * 3;
565	                    slot.commit();
566	                }
567	            });
568	            s.spawn(move || {
569	                for i in 0..COUNT {
570	                    let msg = cons.reserve_slot_with::<Msg>(crate::policy::spin).unwrap();
571	                    assert_eq!(msg.seq, i);
572	                    assert_eq!(msg.val, i * 3);
573	                    msg.release();
574	                }
