1	//! Consuming endpoint: [`Consumer`] reserves the oldest unread
2	//! slot, the [`ReadSlot`] guard reads it in place and releases.
3	
4	use core::marker::PhantomData;
5	use core::ops::Deref;
6	use core::sync::atomic::{AtomicU32, Ordering};
7	use zerocopy::{FromBytes, Immutable, KnownLayout};
8	
9	use super::Header;
10	use crate::{Empty, USER_WORDS, check_type, slot_ptr};
11	
12	/// The consuming endpoint: `reserve_slot_with` the oldest
13	/// unread slot, read in place, `release`.
14	pub struct Consumer<'a> {
15	    /// The ring's control block.
16	    header: &'a Header,
17	    /// Base of the slot array.
18	    slots: *mut u8,
19	    /// Geometry snapshot (see [`Ring`](super::Ring)).
20	    slot_size: u32,
21	    /// Slot-position mask (`capacity - 1`).
22	    mask: u32,
23	    _region: PhantomData<&'a [u8]>,
24	}
25	
26	// SAFETY: the handle owns the consumer role; see the Producer
27	// Send rationale.
28	unsafe impl Send for Consumer<'_> {}
29	
30	impl<'a> Consumer<'a> {
31	    /// Build the handle from [`Ring::split`](super::Ring::split)'s
32	    /// geometry snapshot.
33	    pub(crate) fn new(header: &'a Header, slots: *mut u8, slot_size: u32, mask: u32) -> Self {
34	        Consumer {
35	            header,
36	            slots,
37	            slot_size,
38	            mask,
39	            _region: PhantomData,
40	        }
41	    }
42	
43	    /// The header's app-owned scratch line: zeroed at init,
44	    /// never touched by the crate again.
45	    ///
46	    /// - Shared with the peer: treat contents as untrusted
47	    ///   data — store values, never addresses to dereference.
48	    /// - See the design doc's "Blocking and user words" for
49	    ///   the wakeup-protocol contract it exists to host.
50	    pub fn user(&self) -> &[AtomicU32; USER_WORDS] {
51	        &self.header.user
52	    }
53	
54	    /// Reserve the oldest unread slot as a `&T`, applying an
55	    /// injected wait policy: retry until a message arrives or
56	    /// the policy gives up → [`Empty`].
57	    ///
58	    /// - Only one slot may be reserved at a time: the guard
59	    ///   holds the `&mut Consumer` borrow, so a second
60	    ///   reservation before the guard is dropped or released
61	    ///   does not compile.
62	    /// - Dropping the guard without [`ReadSlot::release`]
63	    ///   leaves the slot unread — the next reservation
64	    ///   returns it again.
65	    /// - `on_empty` is called after each failed attempt with
66	    ///   the attempt count (0-based, saturating); returning
67	    ///   `false` gives up → `Err(Empty)`. Pass `|_| false`
68	    ///   for a single non-blocking probe.
69	    /// - The wait loop is the reservation itself (the guard
70	    ///   borrows the endpoint, so retrying could not return
71	    ///   it): `consumer_idx` is ours and loaded once; only
